def compare_skill_benchmark(without_skill: dict[str, Any], with_skill: dict[str, Any]) -> dict[str, Any]:
    """Honest paired benchmark comparing identical tasks with/without skills (never fabricates savings)."""
    a_mk = without_skill.get("measurement_kind")
    b_mk = with_skill.get("measurement_kind")
    a_in = without_skill.get("input_tokens")
    b_in = with_skill.get("input_tokens")
    if a_mk != "measured" or b_mk != "measured" or a_in is None or b_in is None or a_in <= 0:
        return {
            "status": "unavailable",
            "reason": "Provider-measured input_tokens required for both paired runs; never fabricate skill token savings.",
            "without_skill": without_skill,
            "with_skill": with_skill,
            "delta_input_tokens": None,
            "delta_pct": None,
        }
    delta = int(a_in) - int(b_in)
    return {
        "status": "measured",
        "without_skill": without_skill,
        "with_skill": with_skill,
        "delta_input_tokens": delta,
        "delta_pct": round(delta * 100.0 / int(a_in), 2),
    }
